#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 50005

static int dist_[MAXN];
static int par_[MAXN];
static int q_[MAXN];
static long long f_[MAXN];

/* BFS em lista de adjacencia (formato CSR).
   blocked: vertice a ser ignorado (-1 = nenhum).
   Preenche dist_ (distancias, -1 se inalcancavel) e par_ (pais).
   Retorna o ultimo vertice desenfileirado (tem distancia maxima,
   pois a fila BFS sai em ordem nao decrescente de distancia). */
static int bfs(int n, const int *start, const int *adj, int src, int blocked) {
    int head = 0, tail = 0;
    for (int i = 1; i <= n; i++) dist_[i] = -1;
    dist_[src] = 0;
    par_[src] = 0;
    q_[tail++] = src;
    while (head < tail) {
        int u = q_[head++];
        for (int e = start[u]; e < start[u + 1]; e++) {
            int w = adj[e];
            if (w == blocked || dist_[w] != -1) continue;
            dist_[w] = dist_[u] + 1;
            par_[w] = u;
            q_[tail++] = w;
        }
    }
    return q_[tail - 1];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int m = n - 1;
    int *eu = malloc(sizeof(int) * (size_t)m);
    int *ev = malloc(sizeof(int) * (size_t)m);
    int *deg = calloc((size_t)n + 2, sizeof(int));

    for (int i = 0; i < m; i++) {
        int x, y;
        if (scanf("%d %d", &x, &y) != 2) return 0;
        eu[i] = x; ev[i] = y;
        deg[x]++; deg[y]++;
    }

    int *start = malloc(sizeof(int) * ((size_t)n + 2));
    int *pos = malloc(sizeof(int) * ((size_t)n + 1));
    int *adj = malloc(sizeof(int) * (size_t)(2 * m));

    start[0] = 0;
    for (int v = 1; v <= n; v++) start[v + 1] = start[v] + deg[v];
    for (int v = 1; v <= n; v++) pos[v] = start[v];
    for (int i = 0; i < m; i++) {
        adj[pos[eu[i]]++] = ev[i];
        adj[pos[ev[i]]++] = eu[i];
    }
    free(pos); free(eu); free(ev); free(deg);

    /* Diametro por BFS dupla */
    int a = bfs(n, start, adj, 1, -1);
    int b = bfs(n, start, adj, a, -1);
    int D = dist_[b];

    printf("%d\n", D + 1); /* ciclo maximo: caminho de D arestas + novo tunel */

    long long count;

    if (D % 2 == 0) {
        /* Centro unico c: toda tupida (caminho de comprimento D) tem c como
           ponto medio; extremos ficam em ramos distintos a distancia D/2. */
        int half = D / 2;
        int c = b;
        for (int i = 0; i < half; i++) c = par_[c];

        /* BFS multi-fonte a partir de c; par_[v] guarda o representante do ramo */
        for (int v = 1; v <= n; v++) dist_[v] = -1;
        int head = 0, tail = 0;
        dist_[c] = 0;
        par_[c] = 0;
        q_[tail++] = c;
        while (head < tail) {
            int u = q_[head++];
            for (int e = start[u]; e < start[u + 1]; e++) {
                int w = adj[e];
                if (dist_[w] != -1) continue;
                dist_[w] = dist_[u] + 1;
                par_[w] = (u == c) ? w : par_[u];
                q_[tail++] = w;
            }
        }

        memset(f_, 0, sizeof(long long) * ((size_t)n + 1));
        for (int v = 1; v <= n; v++)
            if (v != c && dist_[v] == half)
                f_[par_[v]]++;

        long long S = 0, Q = 0;
        for (int v = 1; v <= n; v++) {
            if (f_[v] > 0) {
                S += f_[v];
                Q += f_[v] * f_[v];
            }
        }
        count = (S * S - Q) / 2; /* soma sobre pares de ramos distintos: sum_{i<j} f_i*f_j */
    } else {
        /* Aresta central (c1, c2): toda tupida tem essa aresta como ponto medio;
           extremos a distancia k=(D-1)/2 em lados opostos. */
        int k = (D - 1) / 2;
        int c1 = b;
        for (int i = 0; i < k; i++) c1 = par_[c1];
        int c2 = par_[c1];

        bfs(n, start, adj, c1, c2);
        long long f1 = 0;
        for (int v = 1; v <= n; v++)
            if (dist_[v] == k) f1++;

        bfs(n, start, adj, c2, c1);
        long long f2 = 0;
        for (int v = 1; v <= n; v++)
            if (dist_[v] == k) f2++;

        count = f1 * f2;
    }

    printf("%lld\n", count);
    return 0;
}
